        module = _get_ptx_module()
        grid = ((n + 63) // 64, (n + 63) // 64, 1)
        module.launch(
            "matmul_kernel",
            grid=grid,
            block=(256, 1, 1),
            arguments=[A, B, out, u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return out
